extension Engine where Policy == SyncClientPolicy {
    /// Raises `sync.page` with its payload, binding the event and the payload's
    /// values in one call so the pairing of a name and a type cannot be
    /// constructed inconsistently (NL-to-IR Item C1 Path A). Both carriers are
    /// filled: the typed one a native expression reads, and `data`, which is what
    /// every other reader of `_event.data` binds it from.
    public func raiseSyncPage(more: Bool) {
        raiseExternalWithMeta(
            EventWithMetadata(
                SyncClientEvent.syncPage,
                metadata: EventMetadata(
                    data: payloadJSON(.truth("more", more)),
                    eventType: .externalEvent,
                    typedPayload: SyncClientSyncPagePayload(more: more)
                )
            )
        )
    }

    /// Raises `sync.response` with its payload, binding the event and the payload's
    /// values in one call so the pairing of a name and a type cannot be
