                metadata: EventMetadata(
                    data: payloadJSON(.integer("kind", kind), .integer("status", status), .truth("create", create), .truth("davError", davError), .signed64("now", now), .signed64("retryAfter", retryAfter)),
                    eventType: .externalEvent,
